%%
%[text] ## Integration
%[text] ### Mathematical target: Natural logarithm
%[text] Ref: Compression of an Air-Fuel Mixture, example 9 - 1 (Cengel, pp. 404 - 405)
%[text] Compute:
%[text] $\\int\_{\\rho(0)}^{\\rho} \\frac{d\\rho}{\\rho}$
% Define symbolic variables
syms rho rho0 positive; % Note: declare density as positive, to make the math math pragmatic results.
% (Density is POSITIVE -- no negative mass in this plane of existence)

% Define integrand
f = 1/rho;

% Compute the definite integral from rho0 to rho
integralResult = int(f, rho, rho0, rho);

integralResult_simpl = simplify(integralResult);

% Display
disp(integralResult) %[output:5d5d58a8]
disp(integralResult_simpl) %[output:4761d6b2]
%%
%[text] Note: MATLAB uses `log` for the **natural logarithm.**
%[text] `log(x)` $\\rightarrow \\ln x$
%%
%[text] Rewrite using the *logarithm quotient rule*:
%[text] $\\ln a - ln b = \\ln\\!\\left(\\frac{a}{b}\\right)$
%[text] **Result:**
%[text] $\\ln\\! \\left( \\frac{\\rho} {\\rho\_0} \\right)$
%%
%[text] ### Math target: Natural logarithm
%[text] Compute:
%[text] $\\int\_{\\tau = 0}^{\\tau = t} \\frac{V\_p} {(L\_{bottom} - V\_p t)}$
% Symbolic variables (declare positive to allow log combination)
syms Vp L t tau positive

% Define integrand in dummy variable tau
f = Vp/(L - Vp*tau);

% Compute definite integral from tau = 0 to tau = t
I = int(f, tau, 0, t);

% Simplify and display as a single log of a quotient
I_simpl = simplify(I);        % gives -log(L - Vp*t) + log(L)
I_combined = simplify(I_simpl); % still fine; with 'positive' assumptions it becomes log(L/(L - Vp*t))

disp(I_simpl) %[output:575c99f5]
disp(I_combined) %[output:65efd10f]
%%
%[text] **Result (rewritten, as above):**
%[text] $\\ln\\! \\left( \\frac{L\_{bottom}} {L\_{bottom} - V\_p t} \\right)$
%%
%[text] Plot the nondimensional result:
%[text] $\\rho^\* = \\frac{1}{1-t^\*}$
% Symbolic plot of rho* = 1/(1 - t*), avoiding singularity at t* = 1

% Define symbolic variable and expression
syms t*
rho* = 1/(1 - t*); %[output:6d6ba15a]

% Create a figure
figure
hold on
grid on

% Plot on two intervals that exclude t* = 1
fplot(rho*, [-2, 0.9], 'b', 'LineWidth', 1.5)   % left side
fplot(rho*, [1.1, 4], 'b', 'LineWidth', 1.5)    % right side

% Draw vertical asymptote at t* = 1
rho*l = ylim;                                   % get current y-limits
plot([1 1], rho*l, 'k--', 'LineWidth', 1)       % vertical dashed line

% Labels and title
xlabel('t*')
ylabel('rho*')
title('rho* = 1 / (1 - t*)')
xlim([-2 4])
hold off
%%
% Symbolic plot of y = 1/(1 - x), avoiding singularity at x = 1

% Define symbolic variable and expression
syms x
y = 1/(1 - x);

% Create a figure
figure %[output:6ca0362e]
hold on %[output:6ca0362e]
grid on %[output:6ca0362e]

% Plot on two intervals that exclude x = 1
fplot(y, [-2, 0.9], 'b', 'LineWidth', 1.5)   % left side %[output:6ca0362e]
fplot(y, [1.1, 4], 'b', 'LineWidth', 1.5)    % right side %[output:6ca0362e]

% Draw vertical asymptote at x = 1
yl = ylim;                                   % get current y-limits
plot([1 1], yl, 'k--', 'LineWidth', 1)       % vertical dashed line %[output:6ca0362e]

% Labels and title
xlabel('x') %[output:6ca0362e]
ylabel('y') %[output:6ca0362e]
title('y = 1 / (1 - x)') %[output:6ca0362e]
xlim([-2 4]) %[output:6ca0362e]
hold off %[output:6ca0362e]
%%
%[text] #### Visualize Natural Logarithm
% Plot y = ln(x)
x = linspace(0.01, 10, 1000);   % start slightly above 0
y = log(x);                     % natural log

fig = figure %[output:932943ae] %[output:564092c6]
fig.Theme = 'Light' %[output:6da9b2bb] %[output:564092c6]
plot(x, y, 'b-', 'LineWidth', 1.5) %[output:564092c6]
xlabel('x') %[output:564092c6]
ylabel('ln(x)') %[output:564092c6]
title('Natural Logarithm y = ln(x)') %[output:564092c6]
grid on %[output:564092c6]
xlim([0 10]) %[output:564092c6]
ylim([-5 3]) %[output:564092c6]
%%
%[text] ### Evaluate Fourier coefficient symbolically
%[text] 
%[text] $\\\[C\_m = \\frac{1}{h} \\int\_{-h}^{h} -\\frac{G}{2\\mu} \\left(h^2-y^2\\right) \\cos\\left( \\frac{(2m+1)\\pi y}{2h} \\right) \\,dy$
%[text] Ref: HW 5, Prob. 2, Start-up Poiseuille flow problem (handwritten, p. 116)
%% Evaluate Fourier coefficient C_m symbolically

clear; clc;

syms y h G mu m positive
assumeAlso(m, 'integer');

% Define wave number
k_m = (2*m + 1)*pi/(2*h);

% Define integrand
integrand = -(G/(2*mu))*(h^2 - y^2)*cos(k_m*y) %[output:4dadfa08]

% Compute coefficient C_m
C_m = (1/h)*int(integrand, y, -h, h);

% Simplify result
C_m_simplified = simplify(C_m);

disp('C_m = ') %[output:07e55127]
pretty(C_m_simplified) %[output:1eda0e1d]
%%
% solve_u_pp_eq_0.m
% Solve d^2u/dy^2 = 0 symbolically, apply BCs, and plot example

% Symbolic solution
syms y C1 C2
u = C1*y + C2;                % general solution of u'' = 0

% Example boundary conditions (modify as needed)
y0 = 0; u0 = 1;               % u(y0) = u0
y1 = 2; u1 = 3;               % u(y1) = u1

% Solve for constants C1, C2 from BCs
eqs = [ subs(u,y,y0) == u0, subs(u,y,y1) == u1 ];
sol = solve(eqs, [C1 C2]);
C1sol = simplify(sol.C1);
C2sol = simplify(sol.C2);

% Construct particular solution
u_part = simplify(subs(u, [C1 C2], [C1sol C2sol]));

% Display solution
disp('General solution: u(y) = C1*y + C2') %[output:834b571b]
disp('Particular solution with given BCs:') %[output:1f2f212e]
disp(u_part) %[output:8a969ce9]

% Numeric plot
yn = linspace(min(y0,y1)-0.5, max(y0,y1)+0.5, 200);
un = double(subs(u_part, y, yn));

figure %[output:30464776]
plot(yn, un, 'b-', 'LineWidth', 1.5) %[output:30464776]
hold on %[output:30464776]
plot([y0 y1], [u0 u1], 'ro', 'MarkerFaceColor','r') % BC points %[output:30464776]
hold off %[output:30464776]
xlabel('y') %[output:30464776]
ylabel('u(y)') %[output:30464776]
title('Solution of d^2u/dy^2 = 0') %[output:30464776]
grid on %[output:30464776]
axis tight %[output:30464776]
%%
% plot_quad_scaled.m
% Plot the function y_out = k*(y_in^2 - 1) versus y_in
clear; close all; clc;

% Parameters (adjust k and domain as needed)
k = 2;                       % constant multiplier
ymin = -2; ymax = 2;         % domain for the independent variable y_in
N = 500;                     % number of sample points

% Independent variable (named y_in to avoid confusion with output)
y_in = linspace(ymin, ymax, N);

% Function
y_out = k*(y_in.^2 - 1);

% Plot
figure %[output:7ea82f9f]
plot(y_in, y_out, 'b-', 'LineWidth', 1.5) %[output:7ea82f9f]
xlabel('y (independent variable)') %[output:7ea82f9f]
ylabel('y = k (y^2 - 1)') %[output:7ea82f9f]
title(sprintf('Plot of y = %g (y^2 - 1)', k)) %[output:7ea82f9f]
grid on %[output:7ea82f9f]
axis tight %[output:7ea82f9f]


